import"./hoisted.972BY2g3.js";const n=document.getElementById("shareX"),o=document.getElementById("shareFb"),e=document.getElementById("shareCopy");n?.addEventListener("click",()=>{window.open(`https://twitter.com/intent/tweet?url=${encodeURIComponent(location.href)}&text=${encodeURIComponent(document.title)}`,"_blank","noopener")});o?.addEventListener("click",()=>{window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(location.href)}`,"_blank","noopener")});e?.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(location.href);const t=e.title;e.title="Copied!",setTimeout(()=>{e.title=t},1500)}catch{}});
